export type Theme='meadow'|'forest'|'cave'|'sky'|'desert'|'ice';
export interface Pickup {id:number;x:number;y:number;color:number;hidden:boolean}
export interface Ledge {x:number;y:number;w:number;move?:{axis:'x'|'y';range:number;period:number};fall?:{delay:number;reset:number}}
export interface Enemy {x:number;y:number;kind:'puff'|'hopper'|'bat'|'cloud';range:number}
export interface Level {theme:Theme;width:number;ride:boolean;gaps:[number,number][];ledges:Ledge[];checkpoints:number[];gate:number;wells:number[];rescue:number;beads:Pickup[];enemies:Enemy[];springs:number[];lesson:string}
const pickups=(q:number,items:[number,number,number,boolean?][]):Pickup[]=>items.map(([x,y,color,hidden=false],i)=>({id:1000+q*100+i,x,y,color:q===3?color:12+(i*3+q*7)%24,hidden}));
