export function pickupFor(quest:number,id:number){return levels[quest]?.beads.find(b=>b.id===id);}
export function onSolidGround(level:Level,x:number){return x>=0&&x<=level.width&&!level.gaps.some(([a,b])=>x>a&&x<b);}
export function moonTarget(level:Level,collected:number[],x:number){return level.beads.filter(b=>b.hidden&&!collected.includes(b.id)).sort((a,b)=>Math.abs(a.x-x)-Math.abs(b.x-x))[0];}
